import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE 8
#define KSIZE 11
#define STRIDE 4
#define PAD 2
#define PATCH ((TILE - 1) * STRIDE + KSIZE)

// Direct convolution kernel specialized for: in_channels=3, kernel=11x11,
// stride=4, padding=2. Each block computes an 8x8 tile of the output for one
// (batch, out_channel) pair. The required input patch (39x39x3) and the
// filter weights (11x11x3) are staged in shared memory.
__global__ void conv2d_kernel(const float* __restrict__ input,
                              const float* __restrict__ weight,
                              const float* __restrict__ bias,
                              float* __restrict__ output,
                              int C_in, int H, int W,
                              int C_out, int H_out, int W_out)
{
    __shared__ float s_in[3][PATCH][PATCH];
    __shared__ float s_w[3][KSIZE][KSIZE];

    const int n  = blockIdx.z;
    const int oc = blockIdx.y;

    const int tiles_w = (W_out + TILE - 1) / TILE;
    const int ty0 = (blockIdx.x / tiles_w) * TILE;
    const int tx0 = (blockIdx.x % tiles_w) * TILE;

    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int nthreads = blockDim.x * blockDim.y;

    const int in_y0 = ty0 * STRIDE - PAD;
    const int in_x0 = tx0 * STRIDE - PAD;

    // Cooperatively load the input patch (zero padding out of bounds).
    for (int idx = tid; idx < 3 * PATCH * PATCH; idx += nthreads) {
        const int c   = idx / (PATCH * PATCH);
        const int rem = idx % (PATCH * PATCH);
        const int r   = rem / PATCH;
        const int col = rem % PATCH;
        const int iy = in_y0 + r;
        const int ix = in_x0 + col;
        float v = 0.0f;
        if (iy >= 0 && iy < H && ix >= 0 && ix < W)
            v = input[((n * C_in + c) * H + iy) * W + ix];
        s_in[c][r][col] = v;
    }

    // Cooperatively load this output channel's filter.
    for (int idx = tid; idx < 3 * KSIZE * KSIZE; idx += nthreads) {
        const int c  = idx / (KSIZE * KSIZE);
        const int rem = idx % (KSIZE * KSIZE);
        const int ky = rem / KSIZE;
        const int kx = rem % KSIZE;
        s_w[c][ky][kx] = weight[((oc * 3 + c) * KSIZE + ky) * KSIZE + kx];
    }

    __syncthreads();

    const int oh = ty0 + threadIdx.y;
    const int ow = tx0 + threadIdx.x;

    if (oh < H_out && ow < W_out) {
        float acc = bias[oc];
        const int by = threadIdx.y * STRIDE;
        const int bx = threadIdx.x * STRIDE;
        #pragma unroll
        for (int c = 0; c < 3; ++c) {
            #pragma unroll
            for (int ky = 0; ky < KSIZE; ++ky) {
                #pragma unroll
                for (int kx = 0; kx < KSIZE; ++kx) {
                    acc += s_in[c][by + ky][bx + kx] * s_w[c][ky][kx];
                }
            }
        }
        output[((n * C_out + oc) * H_out + oh) * W_out + ow] = acc;
    }
}

torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(),
                "All tensors must be on CUDA");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(input.size(1) == 3, "kernel expects in_channels == 3");
    TORCH_CHECK(weight.size(1) == 3 && weight.size(2) == KSIZE && weight.size(3) == KSIZE,
                "weight must be (C_out, 3, 11, 11)");

    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c   = bias.contiguous();

    const int N     = input_c.size(0);
    const int C_in  = input_c.size(1);
    const int H     = input_c.size(2);
    const int W     = input_c.size(3);
    const int C_out = weight_c.size(0);

    const int H_out = (H + 2 * PAD - KSIZE) / STRIDE + 1;
    const int W_out = (W + 2 * PAD - KSIZE) / STRIDE + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());

    const int tiles_h = (H_out + TILE - 1) / TILE;
    const int tiles_w = (W_out + TILE - 1) / TILE;

    dim3 block(TILE, TILE);
    dim3 grid(tiles_h * tiles_w, C_out, N);

    conv2d_kernel<<<grid, block>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        output.data_ptr<float>(),
        C_in, H, W, C_out, H_out, W_out);

    return output;
}
"""

_conv_ext = load_inline(
    name="custom_conv2d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.num_classes = num_classes
        # Parameters matching nn.Conv2d(3, 96, kernel_size=11, stride=4, padding=2)
        self.weight = nn.Parameter(torch.empty(96, 3, 11, 11))
        self.bias = nn.Parameter(torch.empty(96))
        # Same default initialization as nn.Conv2d
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = 3 * 11 * 11
        bound = 1.0 / math.sqrt(fan_in)
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return _conv_ext.conv2d_forward(x, self.weight, self.bias)

